# -*- coding: utf-8 -*-
# 10 witnesses × 20 lines (15 story + 5 answers), v2: spoken, concrete, no sermons.
# Quotes in «» from Scripture are word-for-word Synodal. Tags in [brackets] = ElevenLabs v4 delivery.
W = []
def add(id, name, voice, voiceName, model, ref, story, qa):
    W.append(dict(id=id, name=name, voiceId=voice, voiceName=voiceName, model=model, intro=ref, story=story, qa=qa))

